// Nightly freshness (knowledge spec §6): enqueue ONE knowledge-reingest job
// on jobs-mcp. budget_cap: 0 by contract (no model spend on this path).
// The idempotency_key is day-keyed, so a re-fired trigger the same day is an
// idempotent replay (jobs spec §3), never a second run.
const day = $now.toFormat('yyyy-LL-dd');
return [{ json: { rpc: {
  jsonrpc: '2.0', id: `nightly-${day}`, method: 'tools/call',
  params: { name: 'enqueue', arguments: {
    task_type: 'knowledge-reingest',
    payload: { corpus: 'homelab-notes' },
    budget_cap: 0,
    artifacts_out: [],
    idempotency_key: `knowledge-reingest-homelab-notes-${day}`,
  } },
} } }];

// Fail the execution loudly if the enqueue did not succeed (visible in n8n
// execution history; sustained failure surfaces as KnowledgeIndexStale).
const res = $input.first().json; // fullResponse: {data|body, headers, statusCode}
const raw = res.data ?? res.body;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
let payload = null;
for (const line of text.split(/\r?\n/)) if (line.startsWith('data:')) payload = line.slice(5).trim();
if (payload === null) payload = text.trim();
let rpc = null;
try { rpc = JSON.parse(payload); } catch {}
if (res.statusCode !== 200 || !rpc) throw new Error(`jobs-mcp returned ${res.statusCode}`);
if (rpc.error) throw new Error(`rpc error: ${String(rpc.error.message ?? '').slice(0, 200)}`);
let tool = null;
try { tool = JSON.parse(rpc.result?.content?.[0]?.text ?? ''); } catch {}
if (!tool) throw new Error('unparseable enqueue result');
if (rpc.result?.isError) throw new Error(`enqueue failed: ${tool.code} ${String(tool.message ?? '').slice(0, 200)}`);
return [{ json: { job_id: tool.id, idempotent_replay: tool.idempotent_replay === true } }];
